    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1rem;
}

.original-price {
    color: #999;
    text-decoration: line-through;
    font-size: 0.95rem;
}

.sale-price {
    font-size: 1.5rem;
    font-weight: 700;
    color: #f5576c;
}

/* ============================================================================
   Editorial Section
   ============================================================================ */

.editorial-section {
    background-color: #fafafa;
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 2rem;
}

.editorial-card {
    background: white;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.12);
}

.editorial-card:focus-within {
    outline: 2px solid #667eea;
    outline-offset: 2px;
}

.editorial-image {
    width: 100%;
    height: 180px;
    background-size: cover;
    background-position: center;
}

.editorial-content {
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.editorial-title {
    font-size: 1.25rem;
    font-weight: 600;
    color: #1a1a1a;
    margin-bottom: 0.75rem;
}

.editorial-excerpt {
    font-size: 0.95rem;
    color: #666;
    margin-bottom: 1rem;
    flex-grow: 1;
}

.read-more {
    color: #667eea;
    text-decoration: none;
    font-weight: 600;
    transition: color 0.2s;
    display: inline-block;
    width: fit-content;
}

.read-more:hover,
.read-more:focus-visible {
    color: #5568d3;
}

.read-more:focus-visible {
    outline: 2px solid #667eea;
    outline-offset: 2px;
    border-radius: 2px;
}

/* ============================================================================
   Newsletter Section
   ============================================================================ */

.newsletter-section {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
}

.newsletter-content {
    text-align: center;
}

.newsletter-content h2 {
    font-size: 2rem;
    margin-bottom: 0.75rem;
}

.newsletter-content p {
    font-size: 1.1rem;
    margin-bottom: 2rem;
    opacity: 0.95;
}

.newsletter-form {
    display: flex;
    gap: 1rem;
    max-width: 500px;
    margin: 0 auto;
    flex-wrap: wrap;
    justify-content: center;
}

.newsletter-form input {
    flex: 1;
    min-width: 250px;
    padding: 0.75rem 1rem;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
}

.newsletter-form input:focus-visible {
    outline: 2px solid white;
    outline-offset: 2px;
}

.newsletter-form button {
    min-width: 150px;
}

/* ============================================================================
   Footer
   ============================================================================ */

footer {
    background-color: #1a1a1a;
    color: #e0e0e0;
    padding: 3rem 2rem 1rem;
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-section h3 {
    color: white;
    font-size: 1.1rem;
    margin-bottom: 1rem;
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: 0.75rem;
}

.footer-section a {
    color: #e0e0e0;
    text-decoration: none;
    transition: color 0.2s;
}

.footer-section a:hover,
.footer-section a:focus-visible {
    color: #667eea;
}

.footer-section a:focus-visible {
    outline: 2px solid #667eea;
    outline-offset: 2px;
    border-radius: 2px;
}

.social-links {
    display: flex;
    gap: 1.5rem;
    flex-wrap: wrap;
}

.footer-bottom {
    text-align: center;
    padding-top: 2rem;
    border-top: 1px solid #333;
    color: #999;
    font-size: 0.95rem;
}

/* ============================================================================
   Responsive Design
   ============================================================================ */

@media (max-width: 768px) {
    .menu-toggle {
        display: flex;
    }

    .nav-list {
        flex-direction: column;
        gap: 0;
    }

    .nav-link {
        display: block;
        padding: 1rem 0;
        border-bottom: 1px solid #f0f0f0;
    }

    .navbar.closed {
        max-height: 0;
        overflow: hidden;
        border: none;
    }

    .navbar.open {
        max-height: 500px;
    }

    .hero-content h2 {
        font-size: 2rem;
    }

    .hero-content p {
        font-size: 1rem;
    }

    .section-title {
        font-size: 2rem;
    }

    .product-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: 1.5rem;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input,
    .newsletter-form button {
        width: 100%;
        min-width: auto;
    }
}

@media (max-width: 480px) {
    .section-title {
        font-size: 1.75rem;
    }

    .section-subtitle {
        font-size: 1rem;
    }

    .product-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .hero {
        padding: 3rem 1rem;
    }

    section {
        padding: 2rem 1rem;
    }

    .product-card,
    .deal-card,
    .editorial-card {
        border-radius: 6px;
    }
}

/* ============================================================================
   High Contrast / Forced Colors
   ============================================================================ */

@media (prefers-contrast: more) {
    .btn-primary {
        border: 2px solid currentColor;
    }

    .btn-secondary {
        border: 2px solid currentColor;
    }

    .product-card,
    .deal-card,
    .editorial-card {
        border: 2px solid currentColor;
    }
}

/* ============================================================================
   Reduced Motion
   ============================================================================ */

@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

