}

.navbar.closed {
    max-height: 500px;
}

.nav-list {
    list-style: none;
    display: flex;
    gap: 2rem;
    padding: 1rem 0;
}

.nav-link {
    text-decoration: none;
    color: #555;
    font-weight: 500;
    transition: color 0.2s;
    position: relative;
}

.nav-link:hover,
.nav-link:focus-visible {
    color: #667eea;
}

.nav-link:focus-visible {
    outline: 2px solid #667eea;
    outline-offset: 4px;
    border-radius: 2px;
}

/* ============================================================================
