AssistantMessageToolRequest(name='create', tool_call_id='tooluse_XaXGqDGqzvjfplUxGQ9lEq', arguments={'file_text': '/**
 * StyleHub Ecommerce Home Page
 * Vanilla JavaScript for interactivity
 */

// ============================================================================
// Menu Toggle
// ============================================================================

const menuToggle = document.querySelector('.menu-toggle');
const navbar = document.querySelector('.navbar');

if (menuToggle && navbar) {
    menuToggle.addEventListener('click', () => {
        const isOpen = navbar.classList.contains('open');

        if (isOpen) {
            navbar.classList.remove('open');
            navbar.classList.add('closed');
            menuToggle.setAttribute('aria-expanded', 'false');
        } else {
            navbar.classList.remove('closed');
            navbar.classList.add('open');
            menuToggle.setAttribute('aria-expanded', 'true');
        }
    });

    // Close menu when clicking on a nav link
    const navLinks = navbar.querySelectorAll('.nav-link');
    navLinks.forEach(link => {
        link.addEventListener('click', () => {
            navbar.classList.remove('open');
            navbar.classList.add('closed');
            menuToggle.setAttribute('aria-expanded', 'false');
        });
    });

    // Close menu when pressing Escape
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && navbar.classList.contains('open')) {
            navbar.classList.remove('open');
            navbar.classList.add('closed');
            menuToggle.setAttribute('aria-expanded', 'false');
            menuToggle.focus();
        }
    });
}

// ============================================================================
// Cart Functionality
// ============================================================================

class ShoppingCart {
    constructor() {
        this.items = this.loadCart();
        this.initButtons();
    }

    loadCart() {
        const saved = localStorage.getItem('stylehub_cart');
        return saved ? JSON.parse(saved) : [];
    }

    saveCart() {
        localStorage.setItem('stylehub_cart', JSON.stringify(this.items));
    }

    addItem(name, price) {
        const existingItem = this.items.find(item => item.name === name);

        if (existingItem) {
            existingItem.quantity += 1;
        } else {
            this.items.push({
                name,
                price,
                quantity: 1,
                id: Date.now()
            });
        }

        this.saveCart();
        this.showNotification(`${name} added to cart`);
    }

    showNotification(message) {
        // Create notification element
        const notification = document.createElement('div');
        notification.className = 'notification';
        notification.setAttribute('role', 'status');
        notification.setAttribute('aria-live', 'polite');
        notification.textContent = message;

        document.body.appendChild(notification);

        // Trigger animation
        setTimeout(() => notification.classList.add('show'), 10);

        // Remove after 3 seconds
        setTimeout(() => {
            notification.classList.remove('show');
            setTimeout(() => notification.remove(), 300);
        }, 3000);
    }

    initButtons() {
        document.querySelectorAll('[aria-label*="Add"]').forEach(button => {
            button.addEventListener('click', (e) => {
                const card = button.closest('.product-card, .deal-card');
                if (card) {
                    const nameEl = card.querySelector('.product-name, .deal-title');
                    const priceEl = card.querySelector('.price, .sale-price');

